  WritingLesson(id:'wx-a1-01', level:CefrLevel.a1, title:'Introduce yourself', prompt:'Write a short self-introduction: name, city, job/study and one hobby.', guidance:const ['Use complete simple sentences','Use ich + verb','Include four pieces of information'], minWords:30, keywords:const ['ich','wohne','arbeite','gern'], example:'Ich heiße Samir. Ich wohne in Rostock. Ich arbeite an einer Universität. In meiner Freizeit lese ich gern und gehe spazieren.'),
