  WritingLesson(id:'wx-a1-03', level:CefrLevel.a1, title:'My day', prompt:'Describe your normal weekday with morning, work/study and evening.', guidance:const ['Use time expressions','Use present tense','Write at least four sentences'], minWords:40, keywords:const ['morgens','dann','abends'], example:'Morgens stehe ich um sieben Uhr auf. Dann frühstücke ich. Um acht Uhr beginne ich mit der Arbeit. Abends koche ich und lese ein Buch.'),

  WritingLesson(id:'wx-a2-01', level:CefrLevel.a2, title:'Request information', prompt:'Write to a language school asking about course dates, price and timetable.', guidance:const ['Polite opening','Three questions','Reason for interest','Closing'], minWords:70, keywords:const ['kurs','kosten','wann','freundlichen'], example:'Sehr geehrte Damen und Herren, ich interessiere mich für Ihren Deutschkurs. Wann beginnt der nächste Kurs, wie viel kostet er und an welchen Tagen findet der Unterricht statt? Vielen Dank. Mit freundlichen Grüßen'),
  WritingLesson(id:'wx-a2-02', level:CefrLevel.a2, title:'Past weekend', prompt:'Write about last weekend: where you went, what you did, and what you liked.', guidance:const ['Use Perfekt','Sequence events','Give an opinion'], minWords:75, keywords:const ['am wochenende','habe','bin','gefallen'], example:'Am Wochenende bin ich nach Hamburg gefahren. Dort habe ich Freunde besucht und wir haben zusammen gegessen. Danach sind wir am Hafen spazieren gegangen. Der Ausflug hat mir sehr gut gefallen.'),
  WritingLesson(id:'wx-a2-03', level:CefrLevel.a2, title:'Problem at home', prompt:'Write to your landlord about a household problem and ask for a repair appointment.', guidance:const ['Describe problem','Say since when','Ask for appointment','Be polite'], minWords:80, keywords:const ['leider','seit','termin','bitte'], example:'Guten Tag, leider funktioniert die Heizung seit gestern nicht mehr. Die Wohnung ist sehr kalt. Könnten Sie bitte einen Reparaturtermin organisieren? Am Mittwoch bin ich ab 15 Uhr zu Hause.'),

  WritingLesson(id:'wx-b1-01', level:CefrLevel.b1, title:'Course evaluation', prompt:'Write feedback on a course: strengths, one problem and one improvement proposal.', guidance:const ['Balanced tone','Specific example','Concrete suggestion','Conclusion'], minWords:120, keywords:const ['besonders','allerdings','vorschlagen','insgesamt'], example:'Insgesamt hat mir der Kurs gut gefallen. Besonders hilfreich waren die praktischen Beispiele. Allerdings war für die Übungen oft zu wenig Zeit. Ich würde vorschlagen, den Theorieblock etwas zu kürzen und mehr Gruppenarbeit einzuplanen.'),
  WritingLesson(id:'wx-b1-02', level:CefrLevel.b1, title:'Public transport opinion', prompt:'Should city public transport be cheaper? Give your view, reasons and one limitation.', guidance:const ['State position','Give two reasons','Acknowledge limitation','Conclude'], minWords:130, keywords:const ['meiner meinung','außerdem','allerdings','deshalb'], example:'Meiner Meinung nach sollte der öffentliche Nahverkehr günstiger sein. Dadurch könnten mehr Menschen auf das Auto verzichten. Außerdem würden Personen mit geringem Einkommen entlastet. Allerdings muss eine gute Finanzierung gesichert sein. Deshalb halte ich günstigere Tickets zusammen mit verlässlichen Verbindungen für sinnvoll.'),
  WritingLesson(id:'wx-b1-03', level:CefrLevel.b1, title:'Unexpected change', prompt:'Narrate a situation in which an important plan changed unexpectedly and explain how you solved the problem.', guidance:const ['Set context','Describe unexpected event','Explain solution','Reflect on result'], minWords:130, keywords:const ['zuerst','plötzlich','daraufhin','schließlich'], example:'Zuerst wollten wir mit dem Auto fahren. Plötzlich sprang der Motor nicht mehr an. Daraufhin riefen wir einen Freund an und fuhren gemeinsam zum Bahnhof. Schließlich erreichten wir unser Ziel mit dem Zug und kamen nur etwas später an.'),

  WritingLesson(id:'wx-b2-01', level:CefrLevel.b2, title:'Forum contribution', prompt:'Discuss whether universities should require attendance in lectures.', guidance:const ['Introduce controversy','Develop both sides','Use examples','Take a reasoned position'], minWords:190, keywords:const ['einerseits','andererseits','dennoch','meines erachtens'], example:'Eine allgemeine Anwesenheitspflicht wird kontrovers diskutiert. Einerseits kann regelmäßige Teilnahme den Austausch fördern. Andererseits lernen Erwachsene unterschiedlich und tragen Verantwortung für ihren Studienerfolg. Dennoch können verpflichtende Termine dort sinnvoll sein, wo praktische Zusammenarbeit zentral ist. Meines Erachtens sollte deshalb zwischen Vorlesungen und interaktiven Übungen unterschieden werden.'),
  WritingLesson(id:'wx-b2-02', level:CefrLevel.b2, title:'Formal recommendation', prompt:'Recommend measures to reduce unnecessary meetings in an organization.', guidance:const ['Define problem','Propose at least two measures','Discuss trade-offs','Prioritize'], minWords:190, keywords:const ['maßnahme','zudem','voraussetzung','empfehlen'], example:'Als erste Maßnahme empfehle ich, für jede Besprechung ein klares Ziel und eine Agenda zu verlangen. Zudem sollten reine Informationsupdates standardmäßig schriftlich erfolgen. Voraussetzung ist allerdings, dass Entscheidungen weiterhin transparent dokumentiert werden. Priorität sollte daher auf der Trennung von Informationsweitergabe und echter Abstimmung liegen.'),
  WritingLesson(id:'wx-b2-03', level:CefrLevel.b2, title:'Study interpretation', prompt:'Explain a fictional correlation without overclaiming causality and propose one follow-up study.', guidance:const ['Report association','Name limitations','Avoid causal language','Propose better design'], minWords:200, keywords:const ['zusammenhang','jedoch','ursache','untersuchung'], example:'Die Daten zeigen einen Zusammenhang zwischen Arbeitsweg und berichteter Zufriedenheit. Daraus folgt jedoch nicht, dass ein längerer Arbeitsweg unmittelbar die Ursache geringerer Zufriedenheit ist. Denkbar sind etwa Unterschiede bei Beruf, Einkommen oder Arbeitszeit. Eine weitere Untersuchung könnte diese Faktoren kontrollieren und dieselben Personen über längere Zeit beobachten.'),

  WritingLesson(id:'wx-c1-01', level:CefrLevel.c1, title:'Policy brief', prompt:'Write a short policy brief on algorithmic decision systems: benefits, risks, safeguards and recommendation.', guidance:const ['Executive opening','Differentiate efficiency and fairness','Concrete safeguards','Prioritized recommendation'], minWords:260, keywords:const ['effizienz','fairness','transparenz','kontrolle'], example:'Automatisierte Entscheidungssysteme können Effizienz und Konsistenz erhöhen, doch beides garantiert keine Fairness. Risiken entstehen insbesondere durch ungeeignete Trainingsdaten, intransparente Kriterien und fehlende Einspruchsmöglichkeiten. Eine verantwortliche Nutzung erfordert daher dokumentierte Ziele, regelmäßige Prüfungen, transparente Begründungen und wirksame menschliche Kontrolle. Empfehlenswert ist eine stufenweise Einführung in Bereichen mit reversiblen Entscheidungen.'),
  WritingLesson(id:'wx-c1-02', level:CefrLevel.c1, title:'Research critique', prompt:'Critique a study whose large sample yields a statistically significant but very small effect.', guidance:const ['Distinguish significance/effect size','Discuss practical relevance','Mention uncertainty','Avoid dismissiveness'], minWords:260, keywords:const ['signifikant','effektgröße','relevanz','konfidenz'], example:'Der statistisch signifikante Befund ist aufgrund der großen Stichprobe erwartbar, sollte aber nicht mit praktischer Relevanz gleichgesetzt werden. Entscheidend ist die Effektgröße, die hier nur gering ausfällt. Zusätzlich sollte die Unsicherheit der Schätzung anhand eines Konfidenzintervalls betrachtet werden. Der Befund ist somit informativ, rechtfertigt allein aber noch keine weitreichende Intervention.'),
  WritingLesson(id:'wx-c1-03', level:CefrLevel.c1, title:'Mediated argument', prompt:'Present two serious positions in a dispute over remote work and propose a compromise that addresses both.', guidance:const ['Represent both fairly','Identify underlying interests','Propose compromise','State limits'], minWords:270, keywords:const ['befürworter','kritiker','zugleich','kompromiss'], example:'Befürworter flexibler Heimarbeit verweisen auf Autonomie und eingesparte Pendelzeit, während Kritiker den Verlust informeller Abstimmung und erschwerte Einarbeitung betonen. Beide Positionen adressieren legitime Bedürfnisse. Ein tragfähiger Kompromiss könnte flexible Heimarbeit mit wenigen klar begründeten Präsenztagen verbinden. Zugleich sollte regelmäßig geprüft werden, ob diese Regel für unterschiedliche Tätigkeiten gleichermaßen funktioniert.'),

  WritingLesson(id:'wx-c2-01', level:CefrLevel.c2, title:'Conceptual essay', prompt:'Examine whether procedural neutrality can exist without substantive value choices.', guidance:const ['Define terms carefully','Develop tension','Address strongest objection','Reach qualified conclusion'], minWords:360, keywords:const ['neutralität','verfahren','wertentscheidung','gleichwohl'], example:'Verfahrensneutralität ist plausibel, wenn sie als konsistente Anwendung öffentlich begründbarer Regeln verstanden wird. Sie wird problematisch, sobald daraus Wertfreiheit abgeleitet wird: Schon die Auswahl relevanter Kriterien enthält normative Vorentscheidungen. Gleichwohl folgt daraus nicht, dass jedes Verfahren beliebig wäre. Neutralität kann vielmehr als institutionelle Disziplin verstanden werden, Gründe transparent, symmetrisch und revidierbar zu behandeln.'),
  WritingLesson(id:'wx-c2-02', level:CefrLevel.c2, title:'Synthesis under uncertainty', prompt:'Synthesize conflicting evidence about a policy and distinguish disagreement about facts, values and risk tolerance.', guidance:const ['Separate empirical/normative claims','Explain uncertainty','Compare risk tolerance','Synthesize rather than list'], minWords:380, keywords:const ['evidenz','unsicherheit','wert','risiko'], example:'Die scheinbare Uneinigkeit lässt sich teilweise entflechten. Empirisch unterscheiden sich die Studien in der geschätzten Effektgröße; normativ gewichten die Positionen Verteilungsgerechtigkeit unterschiedlich; zusätzlich variiert ihre Toleranz gegenüber seltenen, aber schweren Risiken. Eine Synthese sollte diese Ebenen nicht vermengen: Evidenz reduziert Unsicherheit, entscheidet jedoch nicht allein, welche Risiken gesellschaftlich akzeptabel sind.'),
  WritingLesson(id:'wx-c2-03', level:CefrLevel.c2, title:'Rhetorical reframing', prompt:'Write an editorial that identifies a false binary in a public debate and reframes the underlying question.', guidance:const ['Expose binary','Steelman both sides','Identify hidden premise','Offer better question','Control register'], minWords:380, keywords:const ['gegenüberstellung','einerseits','andererseits','stattdessen'], example:'Die übliche Gegenüberstellung von Innovation und Regulierung suggeriert, Schutz könne nur auf Kosten technischer Entwicklung entstehen. Einerseits ist die Sorge vor Überregulierung berechtigt; andererseits schafft völlige Regelungsunsicherheit eigene Investitionsrisiken. Versteckt bleibt die Annahme, Regeln seien ausschließlich Bremsen. Stattdessen sollte gefragt werden, welche Regeln verlässliche Erwartungen schaffen, ohne Lernprozesse unnötig zu blockieren.'),
];
